def apply_aset_prelaunch_data(apps, schema_editor):
    app_label, model_name = settings.AUTH_USER_MODEL.split('.')
    UserModel = apps.get_model(app_label, model_name)
    AsetPengaturan = apps.get_model('aset', 'AsetPengaturan')
    AsetRuangan = apps.get_model('aset', 'AsetRuangan')
    AsetTeknisi = apps.get_model('aset', 'AsetTeknisi')

    # 1. Pastikan singleton AsetPengaturan tersedia (default terbuka untuk sosialisasi pendataan)
    if not AsetPengaturan.objects.exists():
        AsetPengaturan.objects.create(izinkan_pendaftaran_unit=True)

    # 2. Pastikan akun Mas Febry mendapat hak Aset Admin / Verifikator
    UserModel.objects.filter(username='febry').update(is_aset_admin=True)

    # 3. Normalisasi penamaan Master Ruangan: "Area Poli" -> "Area Tunggu Poli"
    pattern = re.compile(r'(?i)\bArea\s+(?!Tunggu\s+)Poli\b')
    for room in AsetRuangan.objects.filter(nama__icontains='area poli'):
        updated_name = pattern.sub('Area Tunggu Poli', room.nama)
        if updated_name != room.nama:
            room.nama = updated_name
            room.save(update_fields=['nama'])

    # 4. Seed master AsetTeknisi awal dari User IPSRS/Elektromedis & SDM Pegawai aktif
    seen_names = set(n.lower() for n in AsetTeknisi.objects.values_list('nama', flat=True))

    tech_users = UserModel.objects.filter(is_active=True, unit__isnull=False).filter(
        Q(unit__nama__icontains='ipsrs')
        | Q(unit__nama__icontains='elektro')
        | Q(unit__nama__icontains='atem')
    ).select_related('unit')
    for u in tech_users:
        full_name = ' '.join(f'{u.first_name or ""} {u.last_name or ""}'.split()) or u.username
        key = full_name.lower()
        if key not in seen_names:
            unit_lower = (u.unit.nama or '').lower()
            kat = 'elektromedis' if ('elektro' in unit_lower or 'atem' in unit_lower) else 'teknisi_ipsrs'
            AsetTeknisi.objects.create(nama=full_name, kategori=kat, user=u, is_active=True)
            seen_names.add(key)

    try:
        Pegawai = apps.get_model('sdm', 'Pegawai')
        pegawai_qs = Pegawai.objects.filter(is_active=True).filter(
            Q(unit_kerja__icontains='ipsrs')
            | Q(unit_kerja__icontains='elektro')
            | Q(unit_kerja__icontains='atem')
            | Q(jabatan__icontains='teknis')
            | Q(jabatan__icontains='elektro')
            | Q(jabatan__icontains='atem')
            | Q(jabatan__icontains='ipsrs')
        )
        for p in pegawai_qs:
            clean_name = ' '.join((p.nama or '').split())
            if not clean_name:
                continue
            key = clean_name.lower()
            if key not in seen_names:
                text_check = f'{p.unit_kerja} {p.jabatan}'.lower()
                kat = 'elektromedis' if ('elektro' in text_check or 'atem' in text_check) else 'teknisi_ipsrs'
                AsetTeknisi.objects.create(nama=clean_name, kategori=kat, user_id=p.user_id, is_active=True)
                seen_names.add(key)
    except LookupError:
        pass


